	section 6): 471 combinations of category (NULL = all listings), deal, kind,
	brand, place and district with a demand of 500+ a month (kinds 5000+), from
	doc/semantics/structure/landings.csv. Such a page is indexed when it has
	listings; any other combination of the same filters is noindex.
	h1_* / title_* / meta_* / text_*: own texts (stage C), empty = the templates.
	demand: searches a month (Keyword Planner), for the order of links.
	========================================================================== */

return <<<'SQL'
CREATE TABLE landings (
	id SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
	category_id SMALLINT UNSIGNED NULL,
	deal ENUM('sale', 'rent', 'daily') NULL,
	item_type VARCHAR(32) NULL,
	brand VARCHAR(32) NULL,
	city_id SMALLINT UNSIGNED NULL,
	district_id SMALLINT UNSIGNED NULL,
	demand INT UNSIGNED NOT NULL DEFAULT 0,
	h1_en VARCHAR(100) NULL,
	h1_sr VARCHAR(100) NULL,
	title_en VARCHAR(70) NULL,
	title_sr VARCHAR(70) NULL,
	meta_en VARCHAR(160) NULL,
	meta_sr VARCHAR(160) NULL,
	text_en TEXT NULL,
	text_sr TEXT NULL,
	active TINYINT(1) NOT NULL DEFAULT 1,
	PRIMARY KEY (id),
	KEY idx_landings_category (category_id),
	KEY idx_landings_city (city_id),
	CONSTRAINT fk_landings_category FOREIGN KEY (category_id) REFERENCES categories (id) ON DELETE CASCADE,
	CONSTRAINT fk_landings_city FOREIGN KEY (city_id) REFERENCES cities (id) ON DELETE CASCADE,
	CONSTRAINT fk_landings_district FOREIGN KEY (district_id) REFERENCES districts (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

